from taf.fdsw.rc.interfaces.FDSW25A.fdsw import FDSW25A


class FDSW25B(FDSW25A):
    VERSION_NAME = "FDSW25B"
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super().__init__(
            ip_address=ip_address,
            port=port,
            username=username,
            password=password,
            secure=secure,
        )

